+
+describe("view_order_reversed", () => {
+    const add = (state, id) =>
+        reduceFlows(
+            state,
+            flowActions.FLOWS_ADD({
+                flow: { ...TFlow(), id },
+                matching_filters: {},
+            }),
+        );
+    const setReversed = (state, value: boolean) =>
+        reduceFlows(state, OPTIONS_UPDATE({ view_order_reversed: { value } }));
+    const ids = (state) => state.view.map((f) => f.id);
+
+    it("is read from OPTIONS_RECEIVE and OPTIONS_UPDATE", () => {
+        let state = reduceFlows(
+            undefined,
+            OPTIONS_RECEIVE({
+                view_order_reversed: { value: true },
+            } as any),
+        );
+        expect(state.viewOrderReversed).toBe(true);
+        state = setReversed(state, false);
+        expect(state.viewOrderReversed).toBe(false);
+        expect(reduceFlows(state, OPTIONS_UPDATE({}))).toBe(state);
+    });
+
+    it("appends new flows when not reversed", () => {
+        let state = add(add(add(undefined, "a"), "b"), "c");
+        expect(ids(state)).toEqual(["a", "b", "c"]);
+    });
+
+    it("prepends new flows when reversed", () => {
+        let state = setReversed(undefined, true);
+        state = add(add(add(state, "a"), "b"), "c");
+        expect(ids(state)).toEqual(["c", "b", "a"]);
+        expect(state._viewIndex.get("c")).toBe(0);
+        expect(state._viewIndex.get("a")).toBe(2);
+    });
+
+    it("lets a column sort take precedence", () => {
+        let state = setReversed(undefined, true);
+        state = reduceFlows(
+            state,
+            flowActions.setSort({ column: "path", desc: false }),
+        );
+        state = add(add(state, "a"), "b");
+        expect(ids(state)).toEqual(["a", "b"]);
+    });
+});
